html:
{%- set ar = (frappe.local.lang or "en").startswith("ar") -%}
<div class="rq-offer" dir="{{ 'rtl' if ar else 'ltr' }}">
<style>
.rq-offer { font-size: 13px; line-height: 1.7; }
.rq-offer h2 { margin: 0 0 4px; font-size: 20px; }
.rq-offer .muted { color: #6b7280; }
.rq-offer table { width: 100%; border-collapse: collapse; margin: 12px 0; }
.rq-offer th, .rq-offer td { border: 1px solid #d1d5db; padding: 6px 10px; text-align: start; }
.rq-offer td.num { text-align: end; white-space: nowrap; }
.rq-offer .total td, .rq-offer .total th { font-weight: 700; background: #f3f4f6; }
.rq-offer .terms { margin-top: 10px; }
.rq-offer .sign { margin-top: 48px; display: flex; justify-content: space-between; gap: 24px; }
.rq-offer .sign div { flex: 1; border-top: 1px solid #9ca3af; padding-top: 6px; }
</style>
<h2>{{ _("Job Offer") }}</h2>
<div class="muted">{{ doc.company }} · {{ doc.name }} · {{ frappe.format(doc.offer_date, {"fieldtype": "Date"}) }}</div>
<p>{{ _("Dear {0},").format(doc.applicant_name) }}</p>
<p>{{ _("We are pleased to offer you the position of {0} in the {1} department at {2}, starting on {3}.").format(
	_(doc.designation) if doc.designation else _("the advertised job"),
	_(doc.department) if doc.department else "-",
	doc.company, frappe.format(doc.joining_date, {"fieldtype": "Date"})) }}</p>
<table>
<tr><th>{{ _("Basic Salary (Monthly)") }}</th><td class="num">{{ doc.get_formatted("basic_salary") }}</td></tr>
{%- if doc.housing_allowance %}<tr><th>{{ _("Housing Allowance (Monthly)") }}</th><td class="num">{{ doc.get_formatted("housing_allowance") }}</td></tr>{% endif %}
{%- if doc.transport_allowance %}<tr><th>{{ _("Transport Allowance (Monthly)") }}</th><td class="num">{{ doc.get_formatted("transport_allowance") }}</td></tr>{% endif %}
<tr class="total"><th>{{ _("Total Monthly") }}</th><td class="num">{{ doc.get_formatted("total_monthly") }}</td></tr>
</table>
{%- if doc.probation_months %}<p>{{ _("The first {0} months are a probation period.").format(doc.probation_months) }}</p>{% endif %}
{%- if doc.valid_till %}<p>{{ _("This offer is valid until {0}.").format(frappe.format(doc.valid_till, {"fieldtype": "Date"})) }}</p>{% endif %}
{%- if doc.terms %}<div class="terms"><b>{{ _("Terms and Conditions") }}</b>{{ doc.terms }}</div>{% endif %}
<div class="sign">
<div>{{ _("For the company") }}</div>
<div>{{ _("Accepted by the applicant") }}: {{ doc.applicant_name }}</div>
</div>
</div>
